<template><div class="portal-page"><header class="head"><div><h1>Cotizaciones</h1><p>Consulta tus cotizaciones y solicita una nueva</p></div><router-link to="/quotations/new" class="btn">Solicitar cotización</router-link></header><div class="card"><div class="toolbar"><input v-model="search" placeholder="Buscar por referencia o estado..." @input="debounceFetch"></div><div v-if="loading" class="state">Cargando cotizaciones...</div><template v-else><div v-if="!quotations.length" class="state">Aún no hay cotizaciones</div><div v-else class="table-wrap"><table><thead><tr><th>Referencia</th><th>Fecha</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="q in quotations" :key="q.id"><td><router-link :to="`/quotations/${q.id}`">{{q.Ref}}</router-link></td><td>{{q.date}}</td><td>{{formatMoney(q.GrandTotal)}}</td><td><span>{{statusLabel(q.statut)}}</span></td><td><router-link :to="`/quotations/${q.id}`">Ver</router-link></td></tr></tbody></table></div><div v-if="totalRows>pageSize" class="pagination"><button :disabled="page<=1" @click="page--;fetch()">Anterior</button><span>Página {{page}} de {{totalPages}}</span><button :disabled="page>=totalPages" @click="page++;fetch()">Siguiente</button></div></template></div></div></template><script>export default{data(){return{quotations:[],search:'',page:1,pageSize:10,totalRows:0,loading:false,debounce:null}},computed:{totalPages(){return Math.ceil(this.totalRows/this.pageSize)||1}},mounted(){this.fetch()},methods:{async fetch(){this.loading=true;try{const{data}=await axios.get('/portal/quotations',{params:{page:this.page,limit:this.pageSize,search:this.search||undefined}});this.quotations=data.quotations||[];this.totalRows=data.totalRows||0}catch(_){}this.loading=false},debounceFetch(){clearTimeout(this.debounce);this.debounce=setTimeout(()=>{this.page=1;this.fetch()},300)},formatMoney(n){return Number(n||0).toLocaleString('es-HN',{minimumFractionDigits:2,maximumFractionDigits:2})},statusLabel(v){const s=(v||'').toLowerCase();return {approved:'Aprobada',accepted:'Aceptada',completed:'Completada',pending:'Pendiente',requested:'Solicitada',rejected:'Rechazada',cancelled:'Cancelada'}[s]||v||'Pendiente'}}}</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;margin-bottom:1.25rem}.head h1{margin:0}.head p{margin:.2rem 0 0;color:var(--pc-text-muted)}.btn{background:var(--pc-primary);color:#fff;padding:.6rem .9rem;border-radius:8px;text-decoration:none}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);overflow:hidden}.toolbar{padding:1rem}.toolbar input{width:100%;padding:.65rem;border:1px solid var(--pc-border-strong);border-radius:8px;box-sizing:border-box}.state{padding:3rem;text-align:center;color:var(--pc-text-muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.75rem 1rem;border-bottom:1px solid var(--pc-border);text-align:left}th{background:var(--pc-surface-alt)}a{color:var(--pc-primary)}.pagination{display:flex;justify-content:center;gap:1rem;align-items:center;padding:1rem}.pagination button{padding:.5rem 1rem;border:1px solid var(--pc-border-strong);border-radius:8px;background:var(--pc-surface)}</style>